INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am4_l34','apologize','apologise','道歉;美语 -ize,英式 -ise') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
