INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l34','stand up to','',NULL,'/stænd ʌp tuː/','The ideal cannot stand up to a realistic evaluation.','那理想经不起现实的评判。','He stood up to the bully.','他顶住了那个恶霸。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l34','bring on','',NULL,'/brɪŋ ɑːn/','They have brought this trouble on themselves.','这麻烦是他们自己招来的。','Stress can bring on a headache.','压力会引发头痛。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l34','face up to','',NULL,'/feɪs ʌp tuː/','It is wiser to face up to reality.','正视现实更为明智。','He must face up to his mistakes.','他必须正视自己的错误。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l34','to some degree','',NULL,'/tuː sʌm dɪˈɡriː/','Disillusionment is to some degree inevitable.','幻灭在某种程度上不可避免。','I agree with you, to some degree.','我在某种程度上同意你。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',5,'am4_l34_gp1','choice','{"stem":"\"If parents ___ prepared for this reaction, they would not be so hurt.\"(与现在相反的虚拟条件,if 从句用 be 的虚拟形式)","options":["are","were","was","will be"],"answer_index":1,"stem_cn":"若父母对这种反应有所准备,就不会那么受伤。","explanation_cn":"与现在相反的虚拟条件,if 从句里 be 一律用 were。✓ If parents were prepared, … ✗ are / was / will be:虚拟条件 be 用 were。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',5,'am4_l34_gp1','choice','{"stem":"\"If they realized the truth, they ___ be greatly touched.\"(与现在相反的虚拟,主句用‘助动词 + 动词原形’,填那个表‘将会’的情态词)","options":["would","may","will","can"],"answer_index":0,"stem_cn":"若他们明白真相,会深受感动。","explanation_cn":"与现在相反的虚拟,主句用 would + 动词原形;填 would。✓ they would be greatly touched. ✗ will(真实条件)/ can / may:虚拟主句用 would。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',5,'am4_l34_gp1','choice','{"stem":"\"The child would talk more if the parents ___ less critical.\"(与现在相反的虚拟,if 从句用 be 的虚拟形式)","options":["is","are","were","will be"],"answer_index":2,"stem_cn":"若父母少些挑剔,孩子会多说些心里话。","explanation_cn":"与现在相反的虚拟条件,if 从句里 be 用 were。✓ if the parents were less critical. ✗ are / is / will be:虚拟条件 be 用 were。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',5,'am4_l34_gp2','choice','{"stem":"\"The children were ___ cowed to say how they really felt.\"(‘太…以致不能…’,填 cowed 前那个词)","options":["too","so","quite","very"],"answer_index":0,"stem_cn":"孩子们被吓得太厉害,不敢说出真实感受。","explanation_cn":"‘太…以致不能…’= too + 形容词 + to do;填 too。✓ too cowed to say … ✗ so / very / quite:此结构用 too。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',5,'am4_l34_gp2','choice','{"stem":"\"The parent was too proud ___ admit he was wrong.\"(too … 后接不定式,填不定式符号)","options":["for","to","of","at"],"answer_index":1,"stem_cn":"那位家长太要面子,不肯承认自己错了。","explanation_cn":"too … to do,后接不定式;填不定式符号 to。✓ too proud to admit he was wrong. ✗ for / at / of:不定式用 to。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',5,'am4_l34_gp2','choice','{"stem":"\"He is too honest ___ hide his real feelings.\"(too … 后接不定式,填不定式符号)","options":["to","at","for","in"],"answer_index":0,"stem_cn":"他太诚实,藏不住真情实感。","explanation_cn":"too … to do,后接不定式;填不定式符号 to。✓ too honest to hide his feelings. ✗ for / at / in:不定式用 to。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',5,'am4_l34_gp3','choice','{"stem":"\"Foolish parents ___ the adolescents see that they are annoyed.\"(使役动词,后接 sb + 动词原形(不加 to),‘让…看见’,填表‘让’的那个词)","options":["force","let","allow","want"],"answer_index":1,"stem_cn":"糊涂的父母让青少年看出自己在生气。","explanation_cn":"使役动词 let + sb + 动词原形(不加 to),‘让…看见’。✓ let the adolescents see … ✗ want / allow / force(都要接 to do):使役让某人做用 let。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',5,'am4_l34_gp3','choice','{"stem":"\"Do not ___ the child feel that his friends'' homes are better.\"(使役动词,后接 sb + 动词原形(不加 to),‘使…感到’,填表‘使’的那个词)","options":["tell","ask","force","make"],"answer_index":3,"stem_cn":"别让孩子觉得朋友家更好。","explanation_cn":"使役动词 make + sb + 动词原形(不加 to),‘使…感到’。✓ make the child feel … ✗ tell / ask / force(都要接 to do):使役‘使’用 make。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',5,'am4_l34_gp3','choice','{"stem":"\"A wise parent will ___ the child speak his mind freely.\"(使役动词,后接 sb + 动词原形(不加 to),‘让…说’,填表‘让’的那个词)","options":["allow","let","get","permit"],"answer_index":1,"stem_cn":"明智的父母会让孩子畅所欲言。","explanation_cn":"使役动词 let + sb + 动词原形(不加 to),‘让…说’。✓ let the child speak his mind. ✗ allow / permit / get(都要接 to do):使役‘让’用 let。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',5,'am4_l34_gp4','choice','{"stem":"\"Victorian parents kept their dignity ___ retreating behind a strict attitude.\"(‘通过做…’= __ + 动名词,填那个表方式的介词)","options":["for","with","in","by"],"answer_index":3,"stem_cn":"维多利亚时代的父母靠端起严厉架子来维持威严。","explanation_cn":"‘通过做…’= by + 动名词;表方式的介词是 by。✓ by retreating behind an attitude. ✗ with / in / for:表方式‘通过’用 by。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',5,'am4_l34_gp4','choice','{"stem":"\"You win a child''s trust ___ admitting your mistakes.\"(‘通过做…’= __ + 动名词,填那个表方式的介词)","options":["at","by","with","on"],"answer_index":1,"stem_cn":"靠承认自己的错误,你才能赢得孩子的信任。","explanation_cn":"‘通过做…’= by + 动名词;填 by。✓ by admitting your mistakes. ✗ with / on / at:表方式用 by。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',5,'am4_l34_gp4','choice','{"stem":"\"By ___ up to reality, both sides are better off.\"(表方式的‘通过做…’结构,填‘面对’那个动词的动名词)","options":["to face","face","facing","faced"],"answer_index":2,"stem_cn":"靠正视现实,双方都更好过。","explanation_cn":"by + 动名词;填‘面对’那个动词的动名词 facing。✓ By facing up to reality. ✗ faced / face / to face:by 后用动名词。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',5,'am4_l34_gp5','choice','{"stem":"\"The child knows these charges ___ be true.\"(know + sth + 不定式,‘知道…是…’,填不定式符号)","options":["to","that","as","being"],"answer_index":0,"stem_cn":"孩子知道这些指责是真的。","explanation_cn":"know + sth + 不定式,‘知道…是…’;填不定式符号 to。✓ knows these charges to be true. ✗ that / as / being:此结构用 to be。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',5,'am4_l34_gp5','choice','{"stem":"\"Parents believe their own judgment ___ be always right.\"(believe + sth + 不定式,填不定式符号)","options":["as","being","that","to"],"answer_index":3,"stem_cn":"父母以为自己的判断总是对的。","explanation_cn":"believe + sth + 不定式;填不定式符号 to。✓ believe their judgment to be right. ✗ that / as / being:此结构用 to be。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',5,'am4_l34_gp5','choice','{"stem":"\"We found the ideal ___ be far higher than most parents deserve.\"(find + sth + 不定式,填不定式符号)","options":["being","to","that","as"],"answer_index":1,"stem_cn":"我们发现那理想被抬得远高于多数父母配得上的。","explanation_cn":"find + sth + 不定式;填不定式符号 to。✓ found the ideal to be far higher than deserved. ✗ that / as / being:此结构用 to be。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',5,'am4_l34_gp6','choice','{"stem":"\"A loss of one''s good opinion when reality falls short is ___.\"(“幻灭,理想破灭”用哪个词)","options":["entertainment","arrangement","advertisement","disillusionment"],"answer_index":3,"stem_cn":"当现实不及理想时失去的美好看法。","explanation_cn":"当现实不及理想时失去的美好看法是 disillusionment(幻灭)。✓ loss of one''s good opinion is disillusionment. ✗ entertainment 娱乐;✗ arrangement 安排;✗ advertisement 广告——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',5,'am4_l34_gp6','choice','{"stem":"\"The quality of being honest and free from pretence is ___.\"(“真诚,诚挚”用哪个词)","options":["majority","curiosity","sincerity","authority"],"answer_index":2,"stem_cn":"诚实、不做作的品质。","explanation_cn":"诚实、不做作的品质是 sincerity(真诚)。✓ being honest and free from pretence is sincerity. ✗ curiosity 好奇;✗ authority 权威;✗ majority 多数——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',5,'am4_l34_gp6','choice','{"stem":"\"A slighting remark that harms someone''s reputation is a ___.\"(“诋毁,中伤”用哪个词)","options":["prize","slur","gift","cheer"],"answer_index":1,"stem_cn":"损害名声的贬损之词。","explanation_cn":"损害名声的贬损之词是 slur(诋毁、中伤)。✓ a slighting remark is a slur. ✗ cheer 欢呼;✗ prize 奖品;✗ gift 礼物——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',6,NULL,'choice','{"stem":"adolescence 的意思是:","options":["青春期","中年","老年","童年"],"answer_index":0,"explanation_cn":"adolescence = 青春期。✓ adolescence is a difficult season."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',6,NULL,'choice','{"stem":"disloyalty 的意思是:","options":["慷慨","勇敢","忠诚","不忠,背叛"],"answer_index":3,"explanation_cn":"disloyalty = 不忠、背叛。✓ accuse them of disloyalty."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',6,NULL,'choice','{"stem":"spiteful 的意思是:","options":["恶意的,怀恨的","耐心的","慷慨的","友善的"],"answer_index":0,"explanation_cn":"spiteful = 恶意的、怀恨的。✓ some spiteful remark."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',6,NULL,'choice','{"stem":"evaluation 的意思是:","options":["命令","庆祝","邀请","评价,评估"],"answer_index":3,"explanation_cn":"evaluation = 评价、评估。✓ a realistic evaluation."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',6,NULL,'choice','{"stem":"resent 的意思是:","options":["憎恨,怨恨","感激","原谅","欣赏"],"answer_index":0,"explanation_cn":"resent = 憎恨、怨恨。✓ into opposition by resenting it."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',6,NULL,'choice','{"stem":"authoritarian 的意思是:","options":["宽容的","专制的,独裁的","随和的","民主的"],"answer_index":1,"explanation_cn":"authoritarian = 专制的、独裁的。✓ an authoritarian attitude."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',7,NULL,'cloze','{"stem":"第 1 空","context":"If parents ___1___ prepared for this reaction, they would not be so hurt. A wise parent will ___2___ the child speak his mind. The child knows these charges ___3___ be true, and respects a parent who admits them. Both sides are better off ___4___ facing up to reality.","blank_no":1,"options":["were","are","was","will be"],"answer_index":0,"explanation_cn":"与现在相反的虚拟条件,if 从句 be 用 were。✓ If parents were prepared, they would not be so hurt."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',7,NULL,'cloze','{"stem":"第 2 空","context":"If parents ___1___ prepared for this reaction, they would not be so hurt. A wise parent will ___2___ the child speak his mind. The child knows these charges ___3___ be true, and respects a parent who admits them. Both sides are better off ___4___ facing up to reality.","blank_no":2,"options":["let","force","tell","ask"],"answer_index":0,"explanation_cn":"使役动词 let + sb + 动词原形。✓ a wise parent will let the child speak his mind."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',7,NULL,'cloze','{"stem":"第 3 空","context":"If parents ___1___ prepared for this reaction, they would not be so hurt. A wise parent will ___2___ the child speak his mind. The child knows these charges ___3___ be true, and respects a parent who admits them. Both sides are better off ___4___ facing up to reality.","blank_no":3,"options":["to","that","as","being"],"answer_index":0,"explanation_cn":"know + sth + 不定式,‘知道…是…’。✓ knows these charges to be true."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',7,NULL,'cloze','{"stem":"第 4 空","context":"If parents ___1___ prepared for this reaction, they would not be so hurt. A wise parent will ___2___ the child speak his mind. The child knows these charges ___3___ be true, and respects a parent who admits them. Both sides are better off ___4___ facing up to reality.","blank_no":4,"options":["by","with","in","for"],"answer_index":0,"explanation_cn":"by + 动名词,表方式。✓ better off by facing up to reality."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',8,NULL,'choice','{"stem":"What do adolescents respect in parents?","options":["A parent who admits when he is wrong, ignorant, or unfair","A parent who never explains anything","A parent who is always strict","A parent who gives them money"],"answer_index":0,"explanation_cn":"录音说:青少年敬重一个肯承认自己有错、无知或不公的父母。✓ admits when wrong."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',8,NULL,'choice','{"stem":"Why is some disillusionment with parents inevitable?","options":["Parents hide everything","Children never loved their parents","Parents are always bad people","Children hold so high an ideal of their parents that reality cannot match it"],"answer_index":3,"explanation_cn":"录音说:孩子把父母的理想抬得太高,现实几乎无法与之相称,故幻灭难免。✓ high ideal vs reality."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',8,NULL,'choice','{"stem":"What did Victorian parents wrongly believe kept their dignity?","options":["Playing with their children","Admitting all their mistakes","Retreating behind an unreasoning, authoritarian attitude","Giving in to every demand"],"answer_index":2,"explanation_cn":"录音说:维多利亚时代的父母误以为躲在专制架子后就能维持威严。✓ authoritarian retreat."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',9,NULL,'choice','{"stem":"你想说\"若父母对这种反应有所准备,就不会那么受伤\"(虚拟条件句):","options":["If parents were prepared for this reaction, they would not be so hurt.","If parents were prepared for this reaction, they will not be so hurt.","If parents was prepared for this reaction, they would not be so hurt.","If parents are prepared for this reaction, they would not be so hurt."],"answer_index":0,"explanation_cn":"与现在相反的虚拟条件:if 从句 be 用 were(不用 are/was)、主句用 would + 动词原形(不用 will)。✓ If … were …, … would … 场合:说“(与事实相反)若…就会…”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',9,NULL,'choice','{"stem":"你想说\"孩子们被吓得太厉害,不敢说出真实感受\"(too … to do):","options":["The children were too cowed to saying how they really felt.","The children were too cowed to say how they really felt.","The children were too cowed that they could not say how they really felt.","The children were so cowed to say how they really felt."],"answer_index":1,"explanation_cn":"too + 形容词 + to do,‘太…以致不能…’;用 too … to do(不用 too … that、也不用 so … to)、to 后接原形 say(不写 saying)。✓ too cowed to say … 场合:说“太…以致做不了…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',9,NULL,'choice','{"stem":"你想说\"靠承认自己的错误,你才能赢得孩子的信任\"(by + 动名词):","options":["You win a child''s trust by to admit your mistakes.","You win a child''s trust with admitting your mistakes.","You win a child''s trust by admitting your mistakes.","You win a child''s trust by admit your mistakes."],"answer_index":2,"explanation_cn":"by + 动名词表方式;用 by(不用 with)、by 后接动名词 admitting(不写原形 admit、不写 to admit)。✓ by admitting … 场合:说“靠做…(来达成)”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',10,NULL,'choice','{"stem":"adolescence 的意思是:","options":["中年","老年","童年","青春期"],"answer_index":3,"explanation_cn":"adolescence = 青春期。✓ adolescence is a difficult season."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',10,NULL,'choice','{"stem":"resent 的意思是:","options":["感激","憎恨,怨恨","原谅","欣赏"],"answer_index":1,"explanation_cn":"resent = 憎恨、怨恨。✓ into opposition by resenting it."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',10,NULL,'choice','{"stem":"\"If parents ___ prepared for this reaction, they would not be so hurt.\"(与现在相反的虚拟条件,if 从句用 be 的虚拟形式)","options":["were","will be","was","are"],"answer_index":0,"stem_cn":"若父母对这种反应有所准备,就不会那么受伤。","explanation_cn":"与现在相反的虚拟条件,if 从句 be 用 were。✓ If parents were prepared … ✗ are / was / will be。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',10,NULL,'choice','{"stem":"\"The children were ___ cowed to say how they really felt.\"(‘太…以致不能…’,填 cowed 前那个词)","options":["very","quite","too","so"],"answer_index":2,"stem_cn":"孩子们被吓得太厉害,不敢说出真实感受。","explanation_cn":"‘太…以致不能…’用 too。✓ too cowed to say … ✗ so / very / quite。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',10,NULL,'choice','{"stem":"\"face up to\" 的意思是:","options":["忘记","勇敢面对,正视","推迟","逃避"],"answer_index":1,"explanation_cn":"face up to = 勇敢面对、正视。✓ face up to reality."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',10,NULL,'choice','{"stem":"\"stand up to\" 的意思是:","options":["坐下","服从","经得起,顶得住","放弃"],"answer_index":2,"explanation_cn":"stand up to = 经得起、顶得住。✓ cannot stand up to a realistic evaluation."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',10,NULL,'choice','{"stem":"According to the passage, what kind of parent does the adolescent respect?","options":["One who is always right in his own eyes","One who never talks to the child","One who is coldly authoritarian","One who admits when he is wrong, ignorant, or unfair"],"answer_index":3,"passage":"Adolescence is a difficult season for parents as much as for the young. Parents are often hurt when their children praise the homes of their friends, taking it as a slur on their own cooking, or housekeeping, or furniture — and they are often foolish enough to let the youngsters see that they are annoyed. They may even accuse them of disloyalty, or make some spiteful remark about the friends'' families. Such a loss of dignity, and such a descent into childish behavior, only makes things worse. Before long the parents are complaining that the child has grown secretive and tells them nothing; yet they seldom realize that they have brought this on themselves. Some disillusionment with one''s parents, however good and adequate they may be, is to some degree inevitable. Most children hold so high an ideal of their parents that, unless the parents have been genuinely unsatisfactory, it can hardly hope to stand up to a realistic evaluation. Parents would be greatly surprised, and deeply touched, if they realized how much belief their children usually place in their character and their infallibility, and how much this faith means to a child. If parents were prepared for this adolescent reaction, and understood that it was a sign that the child was growing up and developing valuable powers of observation and independent judgment, they would not be so hurt, and so would not drive the child into opposition by resenting it. The adolescent, with his passion for sincerity, always respects a parent who admits that he is wrong, or ignorant, or even that he has been unfair or unjust. What the child cannot forgive is the parent''s refusal to admit such charges when the child knows them to be true. Victorian parents believed that they kept their dignity by retreating behind an unreasoning, authoritarian attitude; in fact they did nothing of the kind, but their children were then too cowed to let them know how they really felt. Today we tend to go to the other extreme, but on the whole this is a healthier attitude for both the child and the parent. It is always wiser, and safer, to face up to reality, however painful it may be at the moment.","explanation_cn":"课文说:青少年敬重那种肯承认自己有错、无知或不公的父母。✓ admits fault."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',10,NULL,'choice','{"stem":"What can the adolescent not forgive?","options":["A parent who is sometimes tired","A parent''s refusal to admit charges the child knows to be true","A parent who says sorry","A parent who cooks badly"],"answer_index":1,"passage":"Adolescence is a difficult season for parents as much as for the young. Parents are often hurt when their children praise the homes of their friends, taking it as a slur on their own cooking, or housekeeping, or furniture — and they are often foolish enough to let the youngsters see that they are annoyed. They may even accuse them of disloyalty, or make some spiteful remark about the friends'' families. Such a loss of dignity, and such a descent into childish behavior, only makes things worse. Before long the parents are complaining that the child has grown secretive and tells them nothing; yet they seldom realize that they have brought this on themselves. Some disillusionment with one''s parents, however good and adequate they may be, is to some degree inevitable. Most children hold so high an ideal of their parents that, unless the parents have been genuinely unsatisfactory, it can hardly hope to stand up to a realistic evaluation. Parents would be greatly surprised, and deeply touched, if they realized how much belief their children usually place in their character and their infallibility, and how much this faith means to a child. If parents were prepared for this adolescent reaction, and understood that it was a sign that the child was growing up and developing valuable powers of observation and independent judgment, they would not be so hurt, and so would not drive the child into opposition by resenting it. The adolescent, with his passion for sincerity, always respects a parent who admits that he is wrong, or ignorant, or even that he has been unfair or unjust. What the child cannot forgive is the parent''s refusal to admit such charges when the child knows them to be true. Victorian parents believed that they kept their dignity by retreating behind an unreasoning, authoritarian attitude; in fact they did nothing of the kind, but their children were then too cowed to let them know how they really felt. Today we tend to go to the other extreme, but on the whole this is a healthier attitude for both the child and the parent. It is always wiser, and safer, to face up to reality, however painful it may be at the moment.","explanation_cn":"课文说:孩子无法原谅的,是明知指责属实、父母却拒不承认。✓ refusal to admit."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',10,NULL,'choice','{"stem":"Why should parents not be hurt by their child''s growing criticism?","options":["It is a sign of illness","It means the child hates them","It is a sign the child is developing observation and independent judgment","It never really happens"],"answer_index":2,"audio":"Adolescence is a difficult season for parents as much as for the young. Parents are often hurt when their children praise the homes of their friends, taking it as a slur on their own cooking, or housekeeping, or furniture — and they are often foolish enough to let the youngsters see that they are annoyed. They may even accuse them of disloyalty, or make some spiteful remark about the friends'' families. Such a loss of dignity, and such a descent into childish behavior, only makes things worse. Before long the parents are complaining that the child has grown secretive and tells them nothing; yet they seldom realize that they have brought this on themselves. Some disillusionment with one''s parents, however good and adequate they may be, is to some degree inevitable. Most children hold so high an ideal of their parents that, unless the parents have been genuinely unsatisfactory, it can hardly hope to stand up to a realistic evaluation. Parents would be greatly surprised, and deeply touched, if they realized how much belief their children usually place in their character and their infallibility, and how much this faith means to a child. If parents were prepared for this adolescent reaction, and understood that it was a sign that the child was growing up and developing valuable powers of observation and independent judgment, they would not be so hurt, and so would not drive the child into opposition by resenting it. The adolescent, with his passion for sincerity, always respects a parent who admits that he is wrong, or ignorant, or even that he has been unfair or unjust. What the child cannot forgive is the parent''s refusal to admit such charges when the child knows them to be true. Victorian parents believed that they kept their dignity by retreating behind an unreasoning, authoritarian attitude; in fact they did nothing of the kind, but their children were then too cowed to let them know how they really felt. Today we tend to go to the other extreme, but on the whole this is a healthier attitude for both the child and the parent. It is always wiser, and safer, to face up to reality, however painful it may be at the moment.","explanation_cn":"课文说:孩子的批评是他在长大、在培养观察力与独立判断力的信号,父母不必受伤。✓ sign of growing up."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',10,NULL,'choice','{"stem":"What is always wiser and safer, according to the speaker?","options":["To face up to reality, however painful it may be","To pretend to be perfect","To hide behind authority","To avoid the child"],"answer_index":0,"audio":"Adolescence is a difficult season for parents as much as for the young. Parents are often hurt when their children praise the homes of their friends, taking it as a slur on their own cooking, or housekeeping, or furniture — and they are often foolish enough to let the youngsters see that they are annoyed. They may even accuse them of disloyalty, or make some spiteful remark about the friends'' families. Such a loss of dignity, and such a descent into childish behavior, only makes things worse. Before long the parents are complaining that the child has grown secretive and tells them nothing; yet they seldom realize that they have brought this on themselves. Some disillusionment with one''s parents, however good and adequate they may be, is to some degree inevitable. Most children hold so high an ideal of their parents that, unless the parents have been genuinely unsatisfactory, it can hardly hope to stand up to a realistic evaluation. Parents would be greatly surprised, and deeply touched, if they realized how much belief their children usually place in their character and their infallibility, and how much this faith means to a child. If parents were prepared for this adolescent reaction, and understood that it was a sign that the child was growing up and developing valuable powers of observation and independent judgment, they would not be so hurt, and so would not drive the child into opposition by resenting it. The adolescent, with his passion for sincerity, always respects a parent who admits that he is wrong, or ignorant, or even that he has been unfair or unjust. What the child cannot forgive is the parent''s refusal to admit such charges when the child knows them to be true. Victorian parents believed that they kept their dignity by retreating behind an unreasoning, authoritarian attitude; in fact they did nothing of the kind, but their children were then too cowed to let them know how they really felt. Today we tend to go to the other extreme, but on the whole this is a healthier attitude for both the child and the parent. It is always wiser, and safer, to face up to reality, however painful it may be at the moment.","explanation_cn":"课文说:无论当下多难受,正视现实永远更明智、更稳妥。✓ face up to reality."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
